	tempDir := t.TempDir()
	t.Chdir(tempDir)

	// Create settings with user hooks on the same hook types we use
	writeSettingsFile(t, tempDir, `{
  "hooks": {
    "Stop": [
      {
        "matcher": "",
        "hooks": [{"type": "command", "command": "echo user stop hook"}]
      }
    ],
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [{"type": "command", "command": "echo user session start"}]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write",
        "hooks": [{"type": "command", "command": "echo user wrote file"}]
      }
    ]
  }
}`)

	agent := &ClaudeCodeAgent{}
	_, err := agent.InstallHooks(false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	rawHooks := readRawHooks(t, tempDir)

	// Verify Stop has both user hook and our hook
	var stopMatchers []ClaudeHookMatcher
	if err := json.Unmarshal(rawHooks["Stop"], &stopMatchers); err != nil {
		t.Fatalf("failed to parse Stop hooks: %v", err)
	}

	// Count hooks - should have user hook + our hook
	stopHookCount := 0
	hasUserStopHook := false
	hasEntireStopHook := false
	for _, m := range stopMatchers {
		for _, h := range m.Hooks {
			stopHookCount++
			if h.Command == "echo user stop hook" {
				hasUserStopHook = true
			}
			if h.Command == "entire hooks claude-code stop" {
				hasEntireStopHook = true
			}
		}
	}
	if !hasUserStopHook {
		t.Error("user Stop hook was not preserved")
	}
	if !hasEntireStopHook {
		t.Error("Entire Stop hook was not added")
	}

	// Verify SessionStart has both hooks
	var sessionStartMatchers []ClaudeHookMatcher
	if err := json.Unmarshal(rawHooks["SessionStart"], &sessionStartMatchers); err != nil {
		t.Fatalf("failed to parse SessionStart hooks: %v", err)
	}
	hasUserSessionHook := false
	hasEntireSessionHook := false
	for _, m := range sessionStartMatchers {
		for _, h := range m.Hooks {
			if h.Command == "echo user session start" {
				hasUserSessionHook = true
			}
			if h.Command == "entire hooks claude-code session-start" {
				hasEntireSessionHook = true
			}
		}
	}
	if !hasUserSessionHook {
		t.Error("user SessionStart hook was not preserved")
	}
	if !hasEntireSessionHook {
		t.Error("Entire SessionStart hook was not added")
	}

	// Verify PostToolUse has user's Write hook AND our Task/TodoWrite hooks
	var postToolUseMatchers []ClaudeHookMatcher
	if err := json.Unmarshal(rawHooks["PostToolUse"], &postToolUseMatchers); err != nil {
		t.Fatalf("failed to parse PostToolUse hooks: %v", err)
	}
	hasUserWriteHook := false
	hasEntireTaskHook := false
	hasEntireTodoHook := false
	for _, m := range postToolUseMatchers {
		for _, h := range m.Hooks {
			if m.Matcher == "Write" && h.Command == "echo user wrote file" {
				hasUserWriteHook = true
			}
			if m.Matcher == "Task" && h.Command == "entire hooks claude-code post-task" {
				hasEntireTaskHook = true
			}
			if m.Matcher == "TodoWrite" && h.Command == "entire hooks claude-code post-todo" {
				hasEntireTodoHook = true
			}
		}
	}
	if !hasUserWriteHook {
		t.Error("user PostToolUse Write hook was not preserved")
	}
	if !hasEntireTaskHook {
		t.Error("Entire PostToolUse Task hook was not added")
	}
	if !hasEntireTodoHook {
		t.Error("Entire PostToolUse TodoWrite hook was not added")
	}
}

